// Package ui contains the shared, offline workspace navigation and visual system.
package ui

const Head = `<style>
:root{color-scheme:light;--bg:#f3f5f2;--panel:#fff;--soft:#f7f9f6;--ink:#233b33;--muted:#728078;--line:#dce5de;--accent:#22765b;--accent2:#195b47;--tint:#e7f2ea;--key:#f1f5ef;--shadow:0 10px 32px #244c3210}
:root[data-theme=dark]{color-scheme:dark;--bg:#16221d;--panel:#203028;--soft:#26382e;--ink:#e3eee6;--muted:#a4b8aa;--line:#3c5042;--accent:#86c9a4;--accent2:#a7ddbd;--tint:#304e3c;--key:#304435;--shadow:none}
html{scroll-behavior:smooth}body{margin:0!important;background:var(--bg)!important;color:var(--ink)!important;font:15px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif!important}*{box-sizing:border-box}a{color:var(--accent)}button,input,textarea,select{font:inherit}button,a,input,textarea,select{-webkit-tap-highlight-color:transparent}button{cursor:pointer}button:disabled{cursor:default}input:not([type=checkbox]),select,textarea{background:var(--panel)!important;color:var(--ink)!important;border-color:var(--line)!important}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid #76bca4;outline-offset:3px}h1,h2,h3{color:var(--ink);letter-spacing:-.025em}h1{font-size:32px}h2{font-size:20px}.muted,.meta,.small{color:var(--muted)}.card{background:var(--panel)!important;border:1px solid var(--line)!important;border-radius:18px!important;box-shadow:var(--shadow)!important}.primary,.add{background:var(--accent)!important;color:var(--panel)!important}.admin-button,button:not(.primary):not(.topic):not(.key):not(.add):not(.window-calculate):not(.textbtn):not(.back){background:var(--soft);border-color:var(--line);color:var(--ink)}.admin-tools{flex-wrap:wrap}.danger{color:#bd554d!important}.workspace-bar{position:relative;background:var(--panel);border-bottom:1px solid var(--line);padding:0 24px}.workspace-bar-inner{width:100%;max-width:1180px;margin:auto;min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px}.workspace-brand{display:flex;align-items:center;gap:12px;color:var(--ink);font-weight:750;text-decoration:none;min-width:0}.workspace-logo{display:grid;place-items:center;flex:0 0 36px;height:36px;background:var(--accent);color:var(--panel);border-radius:12px}.workspace-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:240px}.workspace-nav{display:flex;align-items:center;gap:5px;flex-wrap:wrap}.workspace-nav a,.workspace-nav button{font-size:14px;padding:8px 12px;border:0;border-radius:9px;text-decoration:none;white-space:nowrap;color:var(--muted);background:transparent}.workspace-nav a:hover,.workspace-nav a[aria-current=page]{background:var(--tint);color:var(--accent);font-weight:650}.workspace-crumb{max-width:1180px;margin:20px auto 0;padding:0 24px;display:flex;gap:8px;align-items:center;color:var(--muted);font-size:12px}.workspace-crumb a{color:var(--muted)}.workspace-hero{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:22px}.workspace-hero h1{margin:0}.workspace-hero p{color:var(--muted);margin:6px 0}.workspace-link{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:10px;background:var(--panel);padding:9px 14px;text-decoration:none}.workspace-link.primary{background:var(--accent);color:var(--panel);white-space:nowrap}.workspace-footer{max-width:1180px;margin:28px auto;padding:20px 24px;border-top:1px solid var(--line);color:var(--muted);font-size:12px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.workspace-shortcuts{display:grid;gap:8px}.workspace-shortcuts a{padding:10px 12px;border:1px solid var(--line);border-radius:10px;color:var(--ink);text-decoration:none}.workspace-shortcuts a:hover{background:var(--tint)}.context-banner{padding:14px 18px;border:1px solid var(--line);border-radius:12px;background:var(--tint);margin:16px 0;overflow-wrap:anywhere}.drop,.badge{background:var(--soft)!important;color:var(--accent)}.drop.over{background:var(--tint)!important}.item{border-color:var(--line)}.attachment{background:var(--soft)!important;border:1px solid var(--line);flex-wrap:wrap;overflow-wrap:anywhere}.empty{color:var(--muted)}dialog{width:min(660px,calc(100% - 32px));border:1px solid var(--line);border-radius:18px;background:var(--panel);color:var(--ink);padding:26px}dialog::backdrop{background:#132a2366}dialog textarea{min-height:240px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.preview-frame{width:100%;height:70vh;border:1px solid var(--line);border-radius:14px;background:#fff}.reply.focused{border:2px solid var(--accent);padding:16px;border-radius:12px;background:var(--tint)}[hidden]{display:none!important}
@media(max-width:760px){.workspace-bar{padding:12px 16px}.workspace-bar-inner{align-items:start;flex-direction:column;gap:10px}.workspace-nav{width:100%;gap:3px}.workspace-nav a,.workspace-nav button{padding:7px 9px;font-size:13px}.workspace-name{max-width:75vw}.workspace-crumb{margin-top:14px;padding:0 16px}.workspace-hero{align-items:start;flex-direction:column}.workspace-hero h1{font-size:27px}.workspace-footer{padding:16px}.window-head,.window-actions{flex-wrap:wrap}.window-name{white-space:nowrap}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.action-menu{display:inline-block;position:relative;vertical-align:middle;white-space:normal}.action-menu>summary{list-style:none;cursor:pointer;color:var(--muted);padding:6px 10px;border-radius:8px;font-size:13px}.action-menu>summary:hover{background:var(--tint)}.action-menu[open]{z-index:80}.action-menu-panel{position:absolute;right:0;top:calc(100% + 5px);z-index:81;display:flex;flex-direction:column;gap:6px;padding:10px;border:1px solid var(--line);background:var(--panel);border-radius:12px;width:max-content;min-width:190px;max-width:min(280px,80vw);max-height:min(60vh,430px);overflow:auto;box-shadow:0 14px 38px #14271b32}.action-menu-panel button,.action-menu-panel a{display:block;width:100%;min-height:36px;text-align:left;white-space:normal;padding:8px 10px;border-radius:8px}.action-menu>summary{min-height:34px;display:flex;align-items:center}.action-menu-panel .workspace-link{display:block}.action-menu-panel>*{width:100%;text-align:left}.admin-tools{align-items:flex-start;justify-content:flex-end;margin:8px 0}.reply .body{font-size:16px;margin:14px 0}.reply{padding:24px 0}.visitor-info{display:flex;gap:10px;align-items:center;font-size:13px}.visitor-avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;flex:0 0 34px;background:var(--tint);color:var(--accent);font-weight:700}.visitor-info time{color:var(--muted);font-size:12px}.client-summary{display:flex;flex-wrap:wrap;gap:5px;margin-top:5px}.client-summary span{font-size:11px;color:var(--muted);padding:2px 6px;border-radius:6px;background:var(--soft);border:1px solid var(--line)}.reply-compose-tools{display:flex;align-items:center;gap:12px;flex-wrap:wrap}#reply-files{max-width:260px;font-size:12px}.reply-queue{display:flex;gap:10px;flex-wrap:wrap;margin:12px 0}.reply-file-card{width:160px;display:flex;gap:7px;flex-direction:column;padding:10px;border:1px solid var(--line);border-radius:12px;overflow-wrap:anywhere}.reply-file-card img{width:100%;height:100px;object-fit:contain;border-radius:8px}#reply-form{padding:22px;background:var(--soft);border-radius:16px;margin-top:24px}#reply-body{min-height:130px}.post .admin-tools{opacity:.6}.post:hover .admin-tools,.post:focus-within .admin-tools{opacity:1}.line-copy{opacity:0}.content-line:hover .line-copy,.content-line:focus-within .line-copy{opacity:1}@media(hover:none){.line-copy{opacity:1}.post .admin-tools{opacity:1}}@media(max-width:600px){.action-menu-panel{max-width:calc(100vw - 36px)}#reply-form{padding:14px}.visitor-info .small{font-size:11px}.reply-file-card{width:130px}}
</style>` + Network

const Nav = `<header class="workspace-bar"><div class="workspace-bar-inner"><a class="workspace-brand" href="/"><span class="workspace-logo">册</span><span class="workspace-name" id="workspace-name">我的工作空间</span></a><nav class="workspace-nav" aria-label="工作空间导航"><a href="/" data-section="forum">论坛笔记</a><a href="/files" data-section="files">文件资料</a><a href="/calculator" data-section="calculator">计算工具</a><details class="action-menu"><summary>更多</summary><div class="action-menu-panel"><a href="/#trash" data-section="trash">回收站</a><a href="/#settings" data-section="settings">设置</a><button type="button" id="workspace-theme" aria-label="切换明暗主题">切换明暗主题</button></div></details></nav></div></header><div class="workspace-crumb"><a href="/">工作空间</a><span>/</span><span id="workspace-location">论坛笔记</span></div>`

const Foot = `<footer class="workspace-footer"><span>记录想法 · 整理资料 · 随手计算</span><a href="/#compose">＋ 写一篇笔记</a></footer><script>
(()=>{const labels={forum:'论坛笔记',files:'文件资料',calculator:'计算工具',trash:'回收站',settings:'设置'};function mark(){let section=location.pathname.startsWith('/files')?'files':location.pathname==='/calculator'?'calculator':location.hash==='#trash'?'trash':location.hash==='#settings'?'settings':'forum';document.querySelectorAll('[data-section]').forEach(a=>{if(a.dataset.section===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.getElementById('workspace-location').textContent=labels[section]}mark();addEventListener('hashchange',mark);try{if(localStorage.getItem('workspace-theme')==='dark')document.documentElement.dataset.theme='dark'}catch(_){}document.getElementById('workspace-theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('workspace-theme',dark?'dark':'light')}catch(_){}};fetch('/api/forum/settings').then(r=>{if(!r.ok)throw Error();return r.json()}).then(s=>{document.getElementById('workspace-name').textContent=s.title||'我的工作空间';if(location.pathname!=='/')document.title=labels[location.pathname.startsWith('/files')?'files':'calculator']+' · '+s.title}).catch(()=>{});})();
</script>` + Live
